package vn.iotstar.controller; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.security.core.Authentication; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.validation.BindingResult; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import org.springframework.web.servlet.mvc.support.RedirectAttributes; import vn.iotstar.dto.ProductDTO; import vn.iotstar.security.CustomUserDetails; import vn.iotstar.service.ProductService; @Controller @RequestMapping("/products") @RequiredArgsConstructor public class ProductController{private final ProductService service;@GetMapping public String list(@RequestParam(defaultValue="")String keyword,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="10")int size,Model m){m.addAttribute("products",service.findAll(keyword,page,size));m.addAttribute("keyword",keyword);m.addAttribute("size",size);return "products/list";}@GetMapping("/create")public String create(Model m){m.addAttribute("productDTO",new ProductDTO());m.addAttribute("mode","create");return "products/form";}@PostMapping("/create")public String create(@Valid @ModelAttribute ProductDTO d,BindingResult r,@RequestParam(required=false)MultipartFile image,Authentication a,Model m,RedirectAttributes ra){if(r.hasErrors()){m.addAttribute("mode","create");return "products/form";}d.setUserId(((CustomUserDetails)a.getPrincipal()).getId());service.create(d,image);ra.addFlashAttribute("success","Tạo sản phẩm thành công.");return "redirect:/products";}@GetMapping("/edit/{id}")public String edit(@PathVariable Long id,Model m){m.addAttribute("productDTO",service.findById(id));m.addAttribute("mode","edit");return "products/form";}@PostMapping("/edit/{id}")public String edit(@PathVariable Long id,@Valid @ModelAttribute ProductDTO d,BindingResult r,@RequestParam(required=false)MultipartFile image,Model m,RedirectAttributes ra){if(r.hasErrors()){m.addAttribute("mode","edit");return "products/form";}service.update(id,d,image);ra.addFlashAttribute("success","Cập nhật sản phẩm thành công.");return "redirect:/products";}@PostMapping("/delete/{id}")public String delete(@PathVariable Long id,RedirectAttributes ra){service.delete(id);ra.addFlashAttribute("success","Xóa sản phẩm thành công.");return "redirect:/products";}}